answer:
async function buy(productId, quantity) {
  const response = await fetch("https://shop.example/api/orders", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ productId: productId, quantity: quantity }),
  });
  const data = await response.json();
  if (!response.ok) {
    return "注文できません: " + data.error;
  }
  return `${data.name}を${data.quantity}個注文しました(${data.total}円)`;
}

console.log(await buy(4, 2));
console.log(await buy(2, 10));
